  function itensCriticos(frenteFiltro){
    return ITENS
      .filter(i => parseInt(i.EstoqueMinimo) > 0)
      .filter(i => !frenteFiltro || i.Frente === frenteFiltro)
      .map(i => {
        const atual = estoqueAtual(i.Title);
        const min = parseInt(i.EstoqueMinimo) || 1;
        return { item: i, atual, min, ratio: atual / min };
      })
      .filter(x => x.ratio < 0.5)
      .sort((a, b) => a.ratio - b.ratio);
  }

  function itensPorSituacao(chave){
    return ITENS
      .filter(i => parseInt(i.EstoqueMinimo) > 0)
      .map(i => ({ item: i, ...situacaoDoItem(i) }))
      .filter(x => x.chave === chave);
  }

  function renderDashboard(){
    const pecas = ITENS.reduce((acc, i) => acc + estoqueAtual(i.Title), 0);
    const abaixoMinimo = itensCriticos().length;

    document.getElementById('kpiPecas').textContent = pecas.toLocaleString('pt-BR');
    document.getElementById('kpiSituacaoCritico').textContent = itensPorSituacao('critico').length;
    document.getElementById('kpiSituacaoBaixo').textContent = itensPorSituacao('baixo').length;
    document.getElementById('kpiSituacaoOk').textContent = itensPorSituacao('ok').length;
    document.getElementById('totalItensCatalogo').textContent = `${abaixoMinimo} itens críticos`;

    renderResumoEstoque();
  }

  function corPorSituacao(chave){
    if(chave === 'critico') return '#c0392b';
    if(chave === 'baixo') return '#b7791f';
    return '#17875a';
  }

  let situacaoResumoAtual = 'critico';

  function renderResumoEstoque(){
    const chave = situacaoResumoAtual;
    const linhas = itensPorSituacao(chave)
      .sort((a, b) => (a.ratio ?? 0) - (b.ratio ?? 0))
      .slice(0, 8);

    const mensagem = { critico: 'Nenhum item crítico agora.', baixo: 'Nenhum item baixo agora.', ok: 'Nenhum item OK no momento.' }[chave];
    document.getElementById('barrasEstoque').innerHTML = linhas.map(x => `
      <div class="barwrap">
        <div class="lbl">${x.item.Title}</div>
        <div class="bar-bg"><div class="bar-fill" style="width:${Math.max(4, Math.min(100, x.ratio * 100))}%; background:${corPorSituacao(x.chave)};"></div></div>
        <div class="num">${x.atual} / ${x.min}</div>
      </div>
    `).join('') || `<div class="desc">${mensagem}</div>`;
  }

  document.querySelectorAll('#view-dashboard .kpi[data-situacao]').forEach(card => {
    card.addEventListener('click', () => {
      situacaoResumoAtual = card.dataset.situacao;
      document.querySelectorAll('#view-dashboard .kpi[data-situacao]').forEach(el => el.classList.toggle('is-active', el === card));
      renderResumoEstoque();
    });
  });

  let configPref = { moeda: 'BRL', formatoData: 'DMY' };

  function formatarData(iso){
    const [y, m, d] = iso.split('-');
    return configPref.formatoData === 'MDY' ? `${m}/${d}/${y}` : `${d}/${m}/${y}`;
  }

  function renderHistorico(){
    const frente = document.getElementById('ddHistFrente').value;
    const tipo = document.getElementById('ddHistTipo').value;
    const hoje = new Date();
    const ha30dias = new Date(hoje.getTime() - 30 * 24 * 60 * 60 * 1000);

    document.getElementById('thHistData').textContent = tipo === 'SAIDA' ? 'Data da Saída' : tipo === 'ENTRADA' ? 'Data da Entrada' : 'Data';
    document.getElementById('histFilterChip').style.display = filtroUltimos30 ? 'inline-flex' : 'none';

    const baseFiltrada = movimentacoes
      .filter(m => !frente || m.frente === frente)
      .filter(m => !tipo || m.tipo === tipo)
      .filter(m => !filtroUltimos30 || new Date(m.data) >= ha30dias)
      .filter(m => !globalBusca || m.colaborador.toLowerCase().includes(globalBusca) || m.item.toLowerCase().includes(globalBusca));

    document.getElementById('kpiHistCritico').textContent = baseFiltrada.filter(m => situacaoDoItemPorTitulo(m.item) === 'critico').length;
    document.getElementById('kpiHistBaixo').textContent = baseFiltrada.filter(m => situacaoDoItemPorTitulo(m.item) === 'baixo').length;
    document.getElementById('kpiHistOk').textContent = baseFiltrada.filter(m => situacaoDoItemPorTitulo(m.item) === 'ok').length;

    const linhas = baseFiltrada
      .filter(m => situacaoHistFiltro.size === 0 || situacaoHistFiltro.has(situacaoDoItemPorTitulo(m.item)))
      .slice()
      .sort((a, b) => numeroIdInterno(a.idInterno) - numeroIdInterno(b.idInterno));

    document.getElementById('tblHistorico').innerHTML = linhas.map(m => `
      <tr>
        <td class="mono">${m.idInterno || '—'}</td>
        <td>${formatarData(m.data)}</td>
        <td>${m.item}</td>
        <td><span class="pill ${m.tipo === 'ENTRADA' ? 'pill-entrada' : 'pill-saida'}">${m.tipo === 'ENTRADA' ? 'ENTRADA' : 'SAÍDA'}</span></td>
        <td class="num">${m.quantidade}</td>
        <td>${m.colaborador || '—'}</td>
        <td>${m.centroCusto || '—'}</td>
        <td class="editcol"><button type="button" class="editbtn" onclick="abrirEdicao(${m.id})" title="Editar movimentação"><svg width="14" height="14" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M13.5 3.5l3 3L7 16H4v-3l9.5-9.5Z"/></svg></button></td>
      </tr>
    `).join('') || '<tr><td colspan="8" class="desc">Nenhuma movimentação para este filtro.</td></tr>';
  }

  ['ddHistFrente','ddHistTipo'].forEach(id => document.getElementById(id).addEventListener('change', () => { filtroUltimos30 = false; renderHistorico(); }));
  document.getElementById('histFilterChip').addEventListener('click', () => { filtroUltimos30 = false; renderHistorico(); });

  ['kpiCardHistCritico', 'kpiCardHistBaixo', 'kpiCardHistOk'].forEach(id => {
    const card = document.getElementById(id);
    card.addEventListener('click', () => {
      const chave = card.dataset.situacao;
      if(situacaoHistFiltro.has(chave)) situacaoHistFiltro.delete(chave);
      else if(situacaoHistFiltro.size < 2) situacaoHistFiltro.add(chave);
      card.classList.toggle('is-active', situacaoHistFiltro.has(chave));
      renderHistorico();
    });
  });

  document.getElementById('kpiCardPecas').addEventListener('click', () => {
    if(currentView !== 'dashboard') switchView('dashboard');
    document.getElementById('tblEstoqueCompleto').closest('.card').scrollIntoView({behavior:'smooth', block:'start'});
  });


  document.querySelectorAll('.kpi').forEach(el => {
    el.setAttribute('tabindex', '0');
    el.setAttribute('role', 'button');
    el.addEventListener('keydown', e => {
      if(e.key === 'Enter' || e.key === ' '){ e.preventDefault(); el.click(); }
    });
  });

  headerSearch.addEventListener('input', () => {
    globalBusca = headerSearch.value.trim().toLowerCase();
    if(currentView === 'historico') renderHistorico();
    if(currentView === 'dashboard'){ renderDashboard(); renderEstoqueCompleto(); }
    if(currentView === 'financeiro') renderFinanceiro();
  });

  function updateHeaderForView(view){
    btnHeaderAction.style.display = '';
    if(view === 'lancamento'){
      crumbLabel.textContent = 'LANÇAMENTO';
      pageTitle.textContent = 'Registrar entrada ou saída de fardamento';
      btnHeaderAction.textContent = 'Registrar movimentação';
      searchWrap.style.visibility = 'hidden';
    } else if(view === 'dashboard'){
      crumbLabel.textContent = 'ESTOQUE';
      pageTitle.textContent = 'Estoque atual, críticos e catálogo completo';
      btnHeaderAction.textContent = '+ Nova movimentação';
      headerSearch.placeholder = 'Buscar por item';
      searchWrap.style.visibility = 'visible';
    } else if(view === 'financeiro'){
      crumbLabel.textContent = 'FINANCEIRO';
      pageTitle.textContent = 'Prestação de contas por Centro de Custo';
      btnHeaderAction.textContent = '+ Nova movimentação';
      headerSearch.placeholder = 'Buscar por centro de custo, item ou colaborador';
      searchWrap.style.visibility = 'visible';
    } else if(view === 'historico'){
      crumbLabel.textContent = 'HISTÓRICO';
      pageTitle.textContent = 'Histórico de movimentações de fardamento';
      btnHeaderAction.textContent = '+ Nova movimentação';
      headerSearch.placeholder = 'Buscar por item ou colaborador';
      searchWrap.style.visibility = 'visible';
    } else {
      crumbLabel.textContent = 'CONFIGURAÇÕES';
      pageTitle.textContent = 'Preferências de exibição';
      searchWrap.style.visibility = 'hidden';
      btnHeaderAction.style.display = 'none';
    }
  }

  function switchView(view){
    currentView = view;
    document.querySelectorAll('.navitem').forEach(b => b.classList.toggle('active', b.dataset.view === view));
    document.querySelectorAll('.view').forEach(v => v.classList.toggle('active', v.id === 'view-' + view));
    updateHeaderForView(view);
    if(view === 'dashboard'){ renderDashboard(); renderEstoqueCompleto(); }
    if(view === 'historico') renderHistorico();
    if(view === 'financeiro') renderFinanceiro();
  }

  function situacaoDoItem(i){
    const atual = estoqueAtual(i.Title);
    const min = parseInt(i.EstoqueMinimo) || 0;
    if(min === 0) return { chave:'semminimo', atual, min, ratio:null };
    const ratio = atual / min;
    if(ratio < 0.5) return { chave:'critico', atual, min, ratio };
    if(ratio === 0.5) return { chave:'baixo', atual, min, ratio };
    return { chave:'ok', atual, min, ratio };
  }

  function pillDaSituacao(chave){
    if(chave === 'critico') return '<span class="pill pill-crit">CRÍTICO</span>';
    if(chave === 'baixo') return '<span class="pill pill-low">BAIXO</span>';
    if(chave === 'ok') return '<span class="pill pill-ok">OK</span>';
    return '<span class="pill pill-neutral">SEM MÍNIMO</span>';
  }

  function classeCorEstoque(chave){
    if(chave === 'critico') return 'num-crit';
    if(chave === 'baixo') return 'num-low';
    if(chave === 'ok') return 'num-ok';
    return '';
  }

  function renderEstoqueCompleto(){
    const frente = document.getElementById('ddEstoqueFrente').value;
    const situacao = document.getElementById('ddEstoqueSituacao').value;

    let linhas = ITENS.map(i => ({ item: i, ...situacaoDoItem(i) }));
    if(frente) linhas = linhas.filter(x => x.item.Frente === frente);
    if(situacao) linhas = linhas.filter(x => x.chave === situacao);
    if(globalBusca) linhas = linhas.filter(x => x.item.Title.toLowerCase().includes(globalBusca));
    linhas.sort((a, b) => (a.ratio ?? 99) - (b.ratio ?? 99));

    document.getElementById('totalEstoqueCompleto').textContent = `${linhas.length} de ${ITENS.length} itens`;
    document.getElementById('tblEstoqueCompleto').innerHTML = linhas.map(x => `
      <tr>
        <td>${x.item.Title}</td>
        <td>${x.item.Frente}</td>
        <td>${x.item.Peca}</td>
        <td>${x.item.Genero}</td>
        <td>${x.item.Tamanho}</td>
        <td class="center ${classeCorEstoque(x.chave)}">${x.atual}</td>
        <td class="center">${x.min}</td>
        <td>${pillDaSituacao(x.chave)}</td>
      </tr>
    `).join('') || '<tr><td colspan="8" class="desc">Nenhum item para este filtro.</td></tr>';
  }

  document.getElementById('ddEstoqueFrente').addEventListener('change', renderEstoqueCompleto);
  document.getElementById('ddEstoqueSituacao').addEventListener('change', renderEstoqueCompleto);

  function valorUnitarioDoItem(title){
    const item = ITENS.find(i => i.Title === title);
    return item ? (parseFloat(item.ValorUnitario) || 0) : 0;
  }

  function pecaDoItem(title){
    const item = ITENS.find(i => i.Title === title);
    return item ? item.Peca : title;
  }

  function formatarReais(valor){
    const num = valor.toLocaleString('pt-BR', {minimumFractionDigits:2, maximumFractionDigits:2});
    const simbolo = configPref.moeda === 'USD' ? 'US$' : configPref.moeda === 'EUR' ? '€' : 'R$';
    return `${simbolo} ${num}`;
  }

  function popularFiltrosFinanceiro(){
    const saidasComCentro = movimentacoes.filter(m => m.tipo === 'SAIDA' && m.centroCusto);

    const selectCentro = document.getElementById('ddFinCentro');
    const centroAtual = selectCentro.value;
    const centros = Array.from(new Set(saidasComCentro.map(m => m.centroCusto))).sort();
    selectCentro.innerHTML = '<option value="">Todos</option>' + centros.map(c => `<option value="${c}">${c}</option>`).join('');
    if(centros.includes(centroAtual)) selectCentro.value = centroAtual;

    const frenteFiltroAtual = document.getElementById('ddFinFrente').value;
    const selectItem = document.getElementById('ddFinItem');
    const itemAtual = selectItem.value;
    const pecas = Array.from(new Set(
      ITENS.filter(i => !frenteFiltroAtual || i.Frente === frenteFiltroAtual).map(i => i.Peca)
    )).sort();
    selectItem.innerHTML = '<option value="">Todos</option>' + pecas.map(p => `<option value="${p}">${p}</option>`).join('');
    if(pecas.includes(itemAtual)) selectItem.value = itemAtual;
  }

  function statusPagoFiltro(m, custoFiltro){
    const pago = comecaComPaOuPg(m.idFinanceiro);
    if(custoFiltro === 'SIM') return pago;
    if(custoFiltro === 'NAO') return !pago;
    return true;
  }

  function saidasFiltradas(){
    const frenteFiltro = document.getElementById('ddFinFrente').value;
    const itemFiltro = document.getElementById('ddFinItem').value;
    const centroFiltro = document.getElementById('ddFinCentro').value;
    const custoFiltro = document.getElementById('ddFinCusto').value;

    return movimentacoes
      .filter(m => m.tipo === 'SAIDA' && m.centroCusto)
      .filter(m => !frenteFiltro || m.frente === frenteFiltro)
      .filter(m => !itemFiltro || pecaDoItem(m.item) === itemFiltro)
      .filter(m => !centroFiltro || m.centroCusto === centroFiltro)
      .filter(m => statusPagoFiltro(m, custoFiltro))
      .filter(m => !globalBusca || m.centroCusto.toLowerCase().includes(globalBusca) || m.colaborador.toLowerCase().includes(globalBusca) || m.item.toLowerCase().includes(globalBusca))
      .slice()
      .sort((a, b) => numeroIdInterno(a.idInterno) - numeroIdInterno(b.idInterno));
  }

  function renderFinanceiro(){
    popularFiltrosFinanceiro();
    const saidas = saidasFiltradas();

    document.getElementById('totalFinLinhas').textContent = `${saidas.length} saídas`;

    document.getElementById('tblFinanceiro').innerHTML = saidas.map(m => {
      const pago = comecaComPaOuPg(m.idFinanceiro);
      return `
        <tr>
          <td class="mono">${m.idInterno || '—'}</td>
          <td>${formatarData(m.data)}</td>
          <td>${m.frente}</td>
          <td>${pecaDoItem(m.item)}</td>
          <td>${m.colaborador || '—'}</td>
          <td>${m.centroCusto}</td>
          <td class="center">${m.quantidade}</td>
          <td class="${pago ? 'fin-id-pago' : ''}"><input type="text" class="fin-id-input" data-fin-id="${m.id}" value="${(m.idFinanceiro || '').replace(/"/g, '&quot;')}" placeholder="—"></td>
          <td class="center">${pago ? '<span class="pill pill-sim">SIM</span>' : '<span class="pill pill-nao">NÃO</span>'}</td>
        </tr>`;
    }).join('') || '<tr><td colspan="9" class="desc">Nenhuma saída com centro de custo para este filtro.</td></tr>';

    const todasSaidasComCentro = movimentacoes.filter(m => m.tipo === 'SAIDA' && m.centroCusto);
    const totalTodas = todasSaidasComCentro.reduce((acc, m) => acc + m.quantidade * valorUnitarioDoItem(m.item), 0);
    const totalNaoLancado = todasSaidasComCentro.filter(m => !comecaComPaOuPg(m.idFinanceiro)).reduce((acc, m) => acc + m.quantidade * valorUnitarioDoItem(m.item), 0);
    const centrosAtivos = new Set(todasSaidasComCentro.map(m => m.centroCusto)).size;
    document.getElementById('kpiFinTotal').textContent = formatarReais(totalTodas);
    document.getElementById('kpiFinNaoLancado').textContent = formatarReais(totalNaoLancado);
    document.getElementById('kpiFinCentros').textContent = centrosAtivos;
    document.getElementById('navCountFin').textContent = centrosAtivos;
  }

  document.getElementById('ddFinFrente').addEventListener('change', renderFinanceiro);
  document.getElementById('ddFinItem').addEventListener('change', renderFinanceiro);
  document.getElementById('ddFinCentro').addEventListener('change', renderFinanceiro);
  document.getElementById('ddFinCusto').addEventListener('change', renderFinanceiro);

  document.getElementById('tblFinanceiro').addEventListener('change', (ev) => {
    const input = ev.target.closest('[data-fin-id]');
    if(!input) return;
    const mov = movimentacoes.find(m => m.id === Number(input.dataset.finId));
    if(!mov) return;
    mov.idFinanceiro = input.value.trim();
    renderFinanceiro();
    renderDashboard();
  });

  function normalizarChaveColuna(chave){
    return chave.toString().trim().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
  }

  function importarPlanilhaFinanceiro(file){
    const leitor = new FileReader();
    leitor.onload = (ev) => {
      let linhas;
      try {
        const dados = new Uint8Array(ev.target.result);
        const pasta = XLSX.read(dados, {type:'array'});
        const primeiraAba = pasta.Sheets[pasta.SheetNames[0]];
        linhas = XLSX.utils.sheet_to_json(primeiraAba, {defval:''});
      } catch(e){
        showToast('Não consegui ler essa planilha.');
        return;
      }
      let casados = 0;
      linhas.forEach(linha => {
        let colInterno = null, colFinanceiro = null;
        Object.keys(linha).forEach(chave => {
          const norm = normalizarChaveColuna(chave);
          if(norm.includes('interno')) colInterno = chave;
          else if(norm.includes('financeiro') || norm.includes('pagamento') || norm.includes('pgto')) colFinanceiro = chave;
        });
        if(!colInterno || !colFinanceiro) return;
        const idInterno = linha[colInterno].toString().trim().toUpperCase();
        const idFinanceiro = linha[colFinanceiro].toString().trim();
        if(!idInterno || !idFinanceiro) return;
        const mov = movimentacoes.find(m => m.tipo === 'SAIDA' && (m.idInterno || '').toUpperCase() === idInterno);
        if(mov){
          mov.idFinanceiro = idFinanceiro;
          casados++;
        }
      });
      showToast(casados > 0 ? `${casados} saída(s) atualizadas com o ID Financeiro.` : 'Nenhum ID Interno da planilha bateu com uma saída existente.');
      renderFinanceiro();
      renderDashboard();
    };
    leitor.readAsArrayBuffer(file);
  }

  function formatarDataHoraAgora(){
    const agora = new Date();
    const dia = String(agora.getDate()).padStart(2, '0');
    const mes = String(agora.getMonth() + 1).padStart(2, '0');
    const hh = String(agora.getHours()).padStart(2, '0');
    const mm = String(agora.getMinutes()).padStart(2, '0');
    return `${dia}/${mes}/${agora.getFullYear()} às ${hh}:${mm}`;
  }

  function exportarExcelFinanceiro(){
    const saidas = saidasFiltradas();
    const colunas = ['ID Interno', 'Data', 'Tipo de Produto', 'Fardamento', 'Colaborador', 'Centro de Custo', 'Quantidade', 'ID Financeiro', 'Lançado'];
    const linhas = saidas.map(m => [
      m.idInterno || '—',
      formatarData(m.data),
      m.frente,
      pecaDoItem(m.item),
      m.colaborador || '—',
      m.centroCusto,
      m.quantidade,
      m.idFinanceiro || '—',
      comecaComPaOuPg(m.idFinanceiro) ? 'SIM' : 'NÃO'
    ]);

    const meta = `Gerado em ${formatarDataHoraAgora()} · Controle de Fardamento · Prestação de contas das saídas`;
    const planilha = XLSX.utils.aoa_to_sheet([[meta], [], colunas, ...linhas]);
    planilha['!merges'] = [{ s: { r: 0, c: 0 }, e: { r: 0, c: colunas.length - 1 } }];
    planilha['!cols'] = colunas.map((coluna, i) => {
      const maiorConteudo = Math.max(coluna.length, ...linhas.map((linha) => String(linha[i] ?? '').length));
      return { wch: Math.max(maiorConteudo + 4, 12) };
    });

    const livro = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(livro, planilha, 'Prestação de contas');

    const arrayBuffer = XLSX.write(livro, { bookType: 'xlsx', type: 'array' });
    const blobExcel = new Blob([arrayBuffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    const url = URL.createObjectURL(blobExcel);
    const link = document.createElement('a');
    link.href = url;
    link.download = 'prestacao-contas-fardamento.xlsx';
    document.body.appendChild(link);
    link.click();
    link.remove();
    URL.revokeObjectURL(url);
  }

  document.getElementById('btnExportarExcelFin').addEventListener('click', exportarExcelFinanceiro);

  document.getElementById('btnImportarPlanilhaFin').addEventListener('click', () => {
    document.getElementById('inputPlanilhaFin').click();
  });
  document.getElementById('inputPlanilhaFin').addEventListener('change', (ev) => {
    const file = ev.target.files[0];
    if(file) importarPlanilhaFinanceiro(file);
    ev.target.value = '';
  });

  document.getElementById('kpiCardFinNaoLancado').addEventListener('click', () => {
    if(currentView !== 'financeiro') switchView('financeiro');
    document.getElementById('ddFinCusto').value = 'NAO';
    renderFinanceiro();
    document.getElementById('tblFinanceiro').closest('.card').scrollIntoView({behavior:'smooth', block:'start'});
  });

  const editOverlay = document.getElementById('editOverlay');
  const editItem = document.getElementById('editItem');
  let editingId = null;

  function abrirEdicao(id){
    const mov = movimentacoes.find(m => m.id === id);
    if(!mov) return;
    editingId = id;
    editItem.innerHTML = itensDaFrente(mov.frente).map(i => `<option value="${i.Title}">${itemLabel(i)}</option>`).join('');
    editItem.value = mov.item;
    editOverlay.classList.add('show');
  }

  function fecharEdicao(){
    editOverlay.classList.remove('show');
    editingId = null;
  }

  document.getElementById('editBtnCancelar').addEventListener('click', fecharEdicao);
  editOverlay.addEventListener('click', e => { if(e.target === editOverlay) fecharEdicao(); });

  document.getElementById('editBtnSalvar').addEventListener('click', () => {
    const mov = movimentacoes.find(m => m.id === editingId);
    if(!mov) return;
    const item = ITENS.find(i => i.Title === editItem.value);
    if(!item){
      showToast('Selecione um item.');
      return;
    }
    mov.item = item.Title;
    fecharEdicao();
    showToast('Movimentação atualizada com sucesso!');
    renderHistorico();
    renderDashboard();
    renderEstoqueCompleto();
    renderFinanceiro();
  });

  document.getElementById('editBtnExcluir').addEventListener('click', () => {
    const id = editingId;
    abrirConfirmacao('Excluir movimentação', 'Excluir esse lançamento definitivamente desta sessão? Isso não pode ser desfeito.', () => {
      movimentacoes = movimentacoes.filter(m => m.id !== id);
      fecharEdicao();
      updateNavCounts();
      renderHistorico();
      renderDashboard();
      renderEstoqueCompleto();
      renderFinanceiro();
      showToast('Movimentação excluída.');
    });
  });

  const confirmOverlay = document.getElementById('confirmOverlay');
  let confirmCallback = null;

  function abrirConfirmacao(titulo, mensagem, onConfirm){
    document.getElementById('confirmTitle').textContent = titulo;
    document.getElementById('confirmMessage').textContent = mensagem;
    confirmCallback = onConfirm;
    confirmOverlay.classList.add('show');
  }

  function fecharConfirmacao(){
    confirmOverlay.classList.remove('show');
    confirmCallback = null;
  }

  document.getElementById('confirmBtnCancelar').addEventListener('click', fecharConfirmacao);
  confirmOverlay.addEventListener('click', e => { if(e.target === confirmOverlay) fecharConfirmacao(); });
  document.getElementById('confirmBtnOk').addEventListener('click', () => {
    const cb = confirmCallback;
    fecharConfirmacao();
    if(cb) cb();
  });

  document.querySelectorAll('.navitem').forEach(btn => {
    btn.addEventListener('click', () => { switchView(btn.dataset.view); fecharMenuMobile(); });
  });

  const btnHamburger = document.getElementById('btnHamburger');
  const sidebarNav = document.getElementById('sidebarNav');
  const sidebarBackdrop = document.getElementById('sidebarBackdrop');

  function abrirMenuMobile(){
    sidebarNav.classList.add('open');
    sidebarBackdrop.classList.add('show');
    btnHamburger.setAttribute('aria-expanded', 'true');
  }
  function fecharMenuMobile(){
    sidebarNav.classList.remove('open');
    sidebarBackdrop.classList.remove('show');
    btnHamburger.setAttribute('aria-expanded', 'false');
  }
  btnHamburger.addEventListener('click', () => {
    sidebarNav.classList.contains('open') ? fecharMenuMobile() : abrirMenuMobile();
  });
  sidebarBackdrop.addEventListener('click', fecharMenuMobile);
  document.addEventListener('keydown', e => { if(e.key === 'Escape') fecharMenuMobile(); });

  btnHeaderAction.addEventListener('click', () => {
    if(currentView === 'lancamento') registrarMovimentacao();
    else switchView('lancamento');
  });

  document.getElementById('cfgDensidade').addEventListener('change', e => {
    document.body.dataset.densidade = e.target.value;
  });
  document.getElementById('cfgTelaInicial').addEventListener('change', e => {
    switchView(e.target.value);
    document.querySelector(`.navitem[data-view="${e.target.value}"]`)?.classList.add('active');
  });
  document.getElementById('cfgMoeda').addEventListener('change', e => {
    configPref.moeda = e.target.value;
    renderFinanceiro();
  });
  document.getElementById('cfgFormatoData').addEventListener('change', e => {
    configPref.formatoData = e.target.value;
    renderHistorico();
  });

  function tick(){
    const d = new Date();
    document.getElementById('clock').textContent = d.toLocaleDateString('pt-BR', {weekday:'long', day:'2-digit', month:'long', year:'numeric'});
  }
  tick();

  refreshItemOptions();
  setTipo('saida');
  fData.value = dataDeHoje();
  updateHeaderForView('lancamento');
  updateNavCounts();
  renderDashboard();
  renderHistorico();
  renderEstoqueCompleto();
  renderFinanceiro();
